objects.ses:
on examine { if flag(lanterna_acesa) { say "A lanterna está acesa, projetando uma luz firme e amarelada ao seu redor." } else if flag(lanterna_com_oleo) { say "A lanterna está cheia de óleo, pronta para ser acesa com fósforos." } else { say "Uma lamparina de metal gasta. Está vazia de óleo." } }
on use with oleo {
  if flag(lanterna_com_oleo) { say "A lanterna já está cheia." }
  else { set lanterna_com_oleo; remove oleo; say "Você despeja o óleo dentro do reservatório da lanterna." }
}
on use with fosforos {
  if flag(lanterna_acesa) { say "A lanterna já está acesa." }
  else if flag(lanterna_com_oleo) { set lanterna_acesa; play "fósforo riscado e a chama de uma lanterna a óleo pegando"; say "Você risca um fósforo e acende o pavio da lanterna. A luz afasta as sombras." }
  else { say "Você tenta acender a lanterna, mas ela está vazia de óleo." }
}

on open {
  if flag(balcão_aberto) { say "O balcão já foi examinado e aberto." }
  else { set balcão_aberto; play "gaveta de madeira emperrada sendo puxada com um rangido"; show fosforos; say "Você abre uma gaveta emperrada no balcão e encontra uma caixinha de fósforos." }
}
on examine {
  if flag(balcão_aberto) { say "Um balcão de madeira rústica com a gaveta aberta." }
  else { say "Um balcão de madeira rústica com uma gaveta fechada que parece emperrada." }
}

on examine {
  say "Você folheia as páginas gastas. A última entrada escrita à mão diz: 'A luz que dorme sob o nicho dos mártires guiará aqueles que buscam a verdade no subsolo'."
}

on examine {
  if flag(fogo_aceso) { say "A lareira brilha com chamas intensas e calorosas, iluminando a cozinha e mantendo brasas vivas." }
  else { say "Uma lareira de pedra escura cheia de cinzas frias." }
}
on use with fosforos {
  if flag(fogo_aceso) { say "A lareira já está acesa." }
  else { set fogo_aceso; play "fósforo riscado e lenha seca pegando fogo numa lareira"; say "Você risca um fósforo e acende as lenhas secas na lareira. O fogo crepita com força." }
}
on use with incenso {
  if flag(fogo_aceso) {
    if flag(incenso_aceso) { say "O incenso já está fumegando." }
    else { set incenso_aceso; play "chiado suave de incenso acendendo sobre brasas"; say "Você aproxima o incenso das brasas da lareira. Ele começa a emanar uma fumaça purificadora e densa." }
  } else {
    say "Você precisa acender a lareira primeiro para ter brasas para o incenso."
  }
}

on open {
  say "Você puxa a gaveta, mas ela está emperrada e trancada por um mecanismo de madeira inchada."
}
on use with "pe de cabra" {
  if flag(gaveta_aberta) { say "A gaveta já foi aberta." }
  else { set gaveta_aberta; play "madeira estalando ao ser forçada com um pé de cabra"; show chave; say "Você enfia o pé de cabra na fresta da gaveta e força até estalar. Dentro há uma chave de ferro enferrujada." }
}
on examine {
  if flag(gaveta_aberta) { say "Uma gaveta arrombada e vazia." }
  else { say "Uma gaveta de carvalho maciço com uma fechadura antiga." }
}

on examine {
  if flag(sino_tocado) { say "O sino monumental vibra levemente após ter sido percutido." }
  else { say "Um sino colossal de bronze maciço, coberto de runas gravadas." }
}

on use with sino {
  if flag(sino_tocado) { say "O sino já foi tocado." }
  else { set sino_tocado; play "badalada profunda e ressonante de um enorme sino de bronze, eco longo"; say "Você desfere um golpe formidável com o martelo de bronze no sino. Um som profundo e ressonante ecoa por todo o mosteiro, penetrando até nas profundezas da terra." }
}

on examine {
  say "O texto revela: 'O sino da torre, quando percutido pelo martelo de bronze, faz os monges perderem o transe místico; a estante do norte na biblioteca esconde a sacristia; e a prata da adaga corta os laços do ritual'."
}

on push {
  if flag(estante_movida) { say "A estante já foi empurrada, revelando a passagem secreta." }
  else {
    if has("manuscrito antigo") {
      set estante_movida; play "estante pesada de carvalho arrastada sobre piso de pedra";
      link norte to Sacristia;
      link sul to Biblioteca in Sacristia;
      say "Você empurra a estante pesada usando as instruções do manuscrito. Ela desliza e revela uma passagem secreta ao norte."
    } else {
      say "Você tenta empurrar a estante, mas ela é pesada demais. Parece haver um mecanismo ou segredo que você ainda não compreende."
    }
  }
}
on examine {
  if flag(estante_movida) { say "Uma estante de livros empurrada para o lado, revelando uma passagem ao norte." }
  else { say "Uma estante alta de carvalho cheia de tomos antigos. Ela parece ligeiramente desalinhada no piso." }
}

on use with "pe de cabra" {
  if flag(painel_aberto) { say "O painel já foi aberto." }
  else { set painel_aberto; play "painel de madeira cedendo com estalo ao ser forçado com um pé de cabra"; show adaga; say "Você usa o pé de cabra para forçar o painel de madeira. Ele cede, revelando uma adaga de prata escondida." }
}
on examine {
  if flag(painel_aberto) { say "Um painel de madeira arrombado." }
  else { say "Um painel de madeira aparafusado firmemente na parede." }
}

on use with lareira {
  if flag(fogo_aceso) {
    if flag(incenso_aceso) { say "O incenso já está fumegando." }
    else { set incenso_aceso; play "chiado suave de incenso acendendo sobre brasas"; say "Você aproxima o incenso das brasas da lareira. Ele começa a emanar uma fumaça purificadora e densa." }
  } else {
    say "Você precisa acender a lareira primeiro para ter brasas para o incenso."
  }
}
on use {
  if flag(fogo_aceso) {
    if flag(incenso_aceso) { say "O incenso já está fumegando." }
    else { set incenso_aceso; play "chiado suave de incenso acendendo sobre brasas"; say "Você acende o incenso nas brasas da lareira." }
  } else {
    say "A lareira está apagada."
  }
}

on examine {
  if flag(colchao_mexido) { say "O colchão está revirado no chão." }
  else { set colchao_mexido; show incenso; say "Você afasta o colchão puído e encontra um bastão de incenso purificador escondido embaixo." }
}

on examine {
  if flag(nicho_examinado) { say "O nicho de pedra está vazio." }
  else { set nicho_examinado; show osso; say "Examinando o fundo do nicho conforme a pista do livro de registros, você encontra um talismã em formato de osso esculpido." }
}

on use with chave {
  if flag(porta_cripta_aberta) { say "A porta de ferro já está destrancada." }
  else {
    set porta_cripta_aberta; play "porta de ferro pesada rangendo ao abrir numa cripta de pedra";
    link leste to "Cripta Profunda";
    say "Você insere a pesada chave de ferro na fechadura e gira. A porta range e se abre para o leste."
  }
}
on examine {
  if flag(porta_cripta_aberta) { say "Uma porta de ferro robusta, agora aberta." }
  else { say "Uma porta de ferro trancada com uma fechadura severa." }
}

scene_2810dff1.ses:
on enter {
  if flag(lanterna_acesa) {
    say "Você desce a escada em caracol para a escuridão da cripta, guiado pela luz da sua lanterna."
  } else {
    play "queda e impacto surdo sobre pedras numa cripta"; end "Você desce a escada na escuridão absoluta, erra o último degrau e despenca sobre as pedras afiadas da cripta. Sua jornada termina no breu."
  }
}

objects.ses:
on use with osso {
  if flag(passagem_aberta) { say "A passagem secreta já está aberta." }
  else {
    set passagem_aberta; play "parede de pedra deslizando com estrondo grave, poeira caindo";
    link norte to "Câmara do Ritual";
    remove osso;
    say "Você encaixa o símbolo de osso na ranhura da parede. A rocha pesada desliza lentamente, revelando uma passagem ao norte."
  }
}
on examine {
  if flag(passagem_aberta) { say "Uma parede de pedra com uma abertura secreta ao norte." }
  else { say "Uma parede de pedra maciça com uma cavidade estranha em formato sinuoso." }
}

scene_29ffc9a8.ses:
on enter {
  if flag(incenso_aceso) {
    say "O fumo protetor do incenso ao redor afasta os vapores venenosos que pairam nesta cripta."
  } else {
    play "chiado de gás venenoso escapando numa câmara de pedra"; end "Uma névoa verde e acre invade seus pulmões instantaneamente. Seus joelhos fraquejam e você desaba sufocado nas cinzas da cripta."
  }
}

objects.ses:
on use with adaga {
  if flag(sino_tocado) {
    set guia_acordado; play "estrondo grave e chamas se apagando de uma vez numa câmara de pedra";
    end "Você empunha a adaga de prata e corta os laços mágicos do altar. Com um estrondo, as chamas azuladas se apagam e os monges desmoronam no chão; ao mesmo tempo, de volta à cabana, seu guia desperta com um suspiro profundo, livre da maldição. Você venceu!";
  } else {
    play "estrondo grave e ameaçador numa câmara de pedra"; end "Você corta os laços com a adaga de prata, mas sem o sino ter sido tocado, os monges despertam de seu transe com um grito ensurdecedor e o cercam. Suas garras frias o dilaceram. Fim de jogo.";
  }
}
on examine {
  say "Um altar profano coberto de runas sangrentas onde o ritual negro é canalizado pela irmandade."
}
